const API = "/api/v1";
const METEO = "/meteo/v1/forecast";
const SAVANT = "/savant";
const CACHE_VER = "w11";

const cache = new Map();
let netErrors = 0, apiCalls = 0;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const REQ_TIMEOUT_MS = 12000;
function withTimeout(promise, ms){
  return new Promise(function(resolve, reject){
    var done=false;
    var t=setTimeout(function(){ if(!done){ done=true; reject(new Error("timeout")); } }, ms);
    promise.then(function(v){ if(!done){ done=true; clearTimeout(t); resolve(v); } },
                 function(e){ if(!done){ done=true; clearTimeout(t); reject(e); } });
  });
}
async function fetchJSON(url){
  let lastErr;
  for(let attempt=0; attempt<3; attempt++){
    try{
      apiCalls++;
      const r = await withTimeout(fetch(url, {headers:{"Accept":"application/json","X-Moonshot":"1"}}), REQ_TIMEOUT_MS);
      if(!r.ok) throw new Error("HTTP "+r.status);
      return await withTimeout(r.json(), REQ_TIMEOUT_MS);
    }catch(e){
      lastErr=e; netErrors++;
      await sleep(200*(attempt+1) + Math.random()*150);
    }
  }
  throw lastErr;
}
async function jget(url){
  if(cache.has(url)) return cache.get(url);
  const run = fetchJSON(url);
  cache.set(url, run);
  try{ return await run; }catch(e){ cache.delete(url); throw e; }
}
async function jgetOnce(url){ return fetchJSON(url); }
async function pool(items, worker, size){
  const out = new Array(items.length); let i = 0;
  const n = Math.min(size, items.length || 1);
  await Promise.all(Array.from({length:n}, async () => {
    while(i < items.length){ const idx = i++; try{ out[idx] = await worker(items[idx], idx); }catch(e){ out[idx] = null; } }
  }));
  return out;
}

const clamp = (x,a,b)=>Math.max(a,Math.min(b,x));
const num = x => (x==null||x==="" ? 0 : (typeof x==="string"?parseFloat(x):x)) || 0;
function parseIP(ip){ if(ip==null) return 0; const p=String(ip).split("."); const w=p[0], f=p[1]; return num(w)+(f==="1"?1/3:f==="2"?2/3:0); }
function tbFrom(st){ return st.totalBases!=null?num(st.totalBases):num(st.hits)+num(st.doubles)+2*num(st.triples)+3*num(st.homeRuns); }
function todayISO(){ const d=new Date(); const off=d.getTimezoneOffset()*60000; return new Date(d-off).toISOString().slice(0,10); }
function shiftISO(iso, days){ const d=new Date(iso+"T12:00:00Z"); d.setUTCDate(d.getUTCDate()+days); return d.toISOString().slice(0,10); }
function daysAgoISO(n){ const d=new Date(); d.setDate(d.getDate()-n); return d.toISOString().slice(0,10); }
function shrinkRate(ev, opp, prior, k){ return (ev + k*prior)/(opp + k); }
function shrinkISO(TB, H, AB, k){ return AB>0 ? (TB - H + k*LG.ISO)/(AB + k) : LG.ISO; }
const esc = s => String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");

function recentIndex(recent, seasonHRrate){
  if(!recent) return {idx:null,HR:0,PA:0,iso:null,avg:null};
  const HR=num(recent.homeRuns),PA=num(recent.plateAppearances),AB=num(recent.atBats),H=num(recent.hits),TB=tbFrom(recent);
  const avg = AB>0 ? H/AB : null, iso = AB>0?(TB-H)/AB:null;
  if(PA<5) return {idx:null,HR,PA,iso,avg};
  const hr=shrinkRate(HR,PA,seasonHRrate,25), isoIdx=shrinkISO(TB,H,AB,25);
  return {idx:clamp(0.6*(hr/LG.HR_PER_PA)+0.4*(isoIdx/LG.ISO),0,3),HR,PA,iso,avg};
}
function seasonPower(st){
  if(!st) return {idx:1,hrRate:LG.HR_PER_PA,iso:LG.ISO,PA:0,HR:0,rawHRrate:0,avg:null};
  const PA=num(st.plateAppearances),AB=num(st.atBats),H=num(st.hits),HR=num(st.homeRuns),TB=tbFrom(st);
  const hrRate=shrinkRate(HR,PA,LG.HR_PER_PA,40), isoIdx=shrinkISO(TB,H,AB,40), iso=AB>0?(TB-H)/AB:LG.ISO;
  return {idx:clamp(0.6*(hrRate/LG.HR_PER_PA)+0.4*(isoIdx/LG.ISO),0,3),hrRate,iso,PA,HR,rawHRrate:PA>0?HR/PA:0,avg:AB>0?H/AB:null};
}
function platoonIndex(sp, fallback){
  if(!sp) return {idx:fallback,PA:0,iso:null,avg:null,HR:0};
  const PA=num(sp.plateAppearances),AB=num(sp.atBats),H=num(sp.hits),HR=num(sp.homeRuns),TB=tbFrom(sp);
  const avg = AB>0 ? H/AB : null, iso=AB>0?(TB-H)/AB:null;
  if(PA<10) return {idx:fallback,PA,iso,avg,HR};
  const hr=shrinkRate(HR,PA,LG.HR_PER_PA,30), isoIdx=shrinkISO(TB,H,AB,30);
  const raw=0.6*(hr/LG.HR_PER_PA)+0.4*(isoIdx/LG.ISO), wgt=clamp(PA/120,0,1);
  return {idx:clamp(wgt*raw+(1-wgt)*fallback,0,3),PA,iso,avg,HR};
}
function pitcherVuln(pt){
  if(!pt.season) return {idx:1,hr9s:null,hr9r:null};
  const ipS=parseIP(pt.season.inningsPitched),hrS=num(pt.season.homeRuns);
  const hr9s=ipS>0?hrS/ipS*9:LG.HR_PER_9;
  let ipR=0,hrR=0,cnt=0;
  for(const s of pt.log){ if(cnt>=3)break; const st=s.stat||{}; const ip=parseIP(st.inningsPitched); if(ip<=0)continue; ipR+=ip; hrR+=num(st.homeRuns); cnt++; }
  const hr9r=ipR>0?hrR/ipR*9:hr9s, wR=clamp(ipR/18,0,0.6), blended=wR*hr9r+(1-wR)*hr9s;
  return {idx:clamp(blended/LG.HR_PER_9,0.2,3),hr9s,hr9r};
}
function bvpIndex(vs, season){
  if(!vs) return {idx:1,HR:0,AB:0,H:0};
  const AB=num(vs.atBats),HR=num(vs.homeRuns),H=num(vs.hits);
  if(AB<3) return {idx:1,HR,AB,H};
  const perAB=(season.rawHRrate>0?season.rawHRrate:LG.HR_PER_PA)*1.09;
  const rate=shrinkRate(HR,AB,perAB,20);
  return {idx:clamp(rate/(perAB||LG.HR_PER_PA),0.4,2.2),HR,AB,H};
}
function computeScore(ix){
  const wsum=Object.values(W).reduce((a,b)=>a+b,0)||1; let raw=0;
  for(const k in W) raw+=(W[k]/wsum)*(ix[k]!=null?ix[k]:1);
  return clamp(Math.round(raw*50),1,100);
}
function tierMeta(s){
  if(s>=75) return {l:"ELITE",c:"t-elite",ring:"ring-elite"};
  if(s>=62) return {l:"STRONG",c:"t-strong",ring:"ring-strong"};
  if(s>=52) return {l:"SOLID",c:"t-solid",ring:""};
  if(s>=42) return {l:"FRINGE",c:"t-fringe",ring:""};
  return {l:"LONGSHOT",c:"t-long",ring:""};
}

